import argparse
import concurrent.futures
import requests
import xml.etree.ElementTree as ET
from threading import Lock

def process_url(url, max_concurrent):
    try:
        response = requests.get(url)
        newline_count = response.text.count('\n')
        return (url, newline_count)
    except Exception:
        return (url, 0)

def parse_xml(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()
    max_concurrent = int(root.attrib['max_concurrent'])
    urls = []
    for url_elem in root.findall('url'):
        urls.append((url_elem.attrib['name'], url_elem.text))
    return max_concurrent, urls

def generate_html(output_path, results):
    with open(output_path, 'w') as f:
        f.write('<html><body><table>\n')
        for name, count in results:
            f.write(f'<tr><td>{name}</td><td>{count}</td></tr>\n')
        f.write('</table></body></html>')

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('xml_path')
    parser.add_argument('output_path')
    args = parser.parse_args()

    max_concurrent, urls = parse_xml(args.xml_path)
    results = []

    with concurrent.futures.ThreadPoolExecutor(max_workers=max_concurrent) as executor:
        futures = []
        for name, url in urls:
            future = executor.submit(process_url, url, max_concurrent)
            futures.append(future)

        for future in concurrent.futures.as_completed(futures):
            results.append(future.result())

    generate_html(args.output_path, results)

if __name__ == '__main__':
    main()
